    /** 投影出来的终态：{ kind, turnKey, completedAt?, completionKey?, at }。 */
    terminal: undefined,
    /** 模型阶段：'none' | 'requested' | 'generating'。 */
    modelPhase: 'none',
    /** 最后一次**执行类证据**的时刻（工具/step/审批/流式）。无关事件不推进它。 */
    lastActivityAt: 0,
    /** 采样时刻。 */
    sampledAt: 0,
